insert into public.items (owner_id, title, description, category, daily_price_satang, location, condition, rules, images, status) values ('00000000-0000-0000-0000-000000000002', 'Canon EOS 80D with 18-135mm lens', 'A reliable APS-C DSLR with a versatile 18-135mm zoom. Comes with two batteries, a charger, a 64 GB SD card and a padded shoulder bag. Great for events, travel and portraits.', 'cameras-photography', 80000, 'Islington, London', 'good', ARRAY['Return with batteries charged', 'Please bring your own SD card if you want to keep the files', 'No use in rain without a cover'], ARRAY['/images/items/cam-01-1.jpg', '/images/items/cam-01-2.jpg'], 'active');
insert into public.items (owner_id, title, description, category, daily_price_satang, location, condition, rules, images, status) values ('00000000-0000-0000-0000-000000000004', 'Sony A7 III full-frame body with two batteries', 'Full-frame mirrorless body for stills and 4K video. Includes two batteries, a dual charger and a cage-free strap. Lens not included.', 'cameras-photography', 120000, 'Clifton, Bristol', 'like_new', ARRAY['ID check at pickup', 'Return with sensor cap on', 'No beach or sand use'], ARRAY['/images/items/cam-02-1.jpg', '/images/items/cam-02-2.jpg'], 'active');
insert into public.items (owner_id, title, description, category, daily_price_satang, location, condition, rules, images, status) values ('00000000-0000-0000-0000-000000000005', '70-200mm f/2.8 telephoto lens for Canon EF', 'Fast telephoto zoom with image stabilisation, ideal for sport, wildlife and stage photography. Supplied with hood, caps and soft case.', 'cameras-photography', 65000, 'Headingley, Leeds', 'good', ARRAY['Keep the lens hood on during use', 'Return in the soft case'], ARRAY['/images/items/cam-03-1.jpg', '/images/items/cam-03-2.jpg'], 'active');
insert into public.items (owner_id, title, description, category, daily_price_satang, location, condition, rules, images, status) values ('00000000-0000-0000-0000-000000000001', 'LED video light kit with two stands', 'Two bi-colour LED panels with dimmers, light stands and a carry bag. Works on mains power or NP-F batteries (two included).', 'cameras-photography', 45000, 'Hackney, London', 'good', ARRAY['Collect and return in the carry bag', 'Mains use indoors only'], ARRAY['/images/items/cam-04-1.jpg'], 'active');
insert into public.items (owner_id, title, description, category, daily_price_satang, location, condition, rules, images, status) values ('00000000-0000-0000-0000-000000000007', 'GoPro action camera with mounts', 'Waterproof action camera with a chest mount, helmet mount, handlebar mount and floating grip. Two batteries included.', 'cameras-photography', 35000, 'Kemptown, Brighton', 'good', ARRAY['Rinse with fresh water after sea use', 'Return all mounts'], ARRAY['/images/items/cam-05-1.jpg'], 'active');
